-- tf-bankrec-r1: set-up of the Daily Bank Reconciliation on a TEST BED database (the isolated restore copy).
-- The same statements BankRec\Schema::ensure() runs (CREATE TABLE IF NOT EXISTS; no existing table altered), plus the
-- privilege rows and the department grants used for the tests. Run with the test-bed database selected.
-- On the development system the System Administrator uses the page's Set up button instead.

CREATE TABLE IF NOT EXISTS `brc_account_map` ( `id` INT UNSIGNED NOT NULL AUTO_INCREMENT, `bank_account_id` INT UNSIGNED NOT NULL, `ledger_code` VARCHAR(50) NOT NULL, `currency` VARCHAR(3) NOT NULL, `rec_start` DATE NOT NULL COMMENT 'first day this account is reconciled', `status` VARCHAR(12) NOT NULL DEFAULT 'proposed' COMMENT 'proposed | confirmed | rejected | superseded', `note` VARCHAR(300) NULL, `created_by` VARCHAR(100) NOT NULL, `created_at` DATETIME NOT NULL, `decided_by` VARCHAR(100) NULL, `decided_at` DATETIME NULL, `decision_note` VARCHAR(300) NULL, PRIMARY KEY (`id`), KEY `idx_brc_map_acct` (`bank_account_id`, `status`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `brc_statement` ( `id` INT UNSIGNED NOT NULL AUTO_INCREMENT, `bank_account_id` INT UNSIGNED NOT NULL, `currency` VARCHAR(3) NOT NULL, `period_from` DATE NOT NULL, `period_to` DATE NOT NULL, `opening_balance` DECIMAL(19,2) NOT NULL COMMENT 'funds: + in credit, − overdrawn', `closing_balance` DECIMAL(19,2) NOT NULL, `total_in` DECIMAL(19,2) NOT NULL DEFAULT 0, `total_out` DECIMAL(19,2) NOT NULL DEFAULT 0, `line_count` INT NOT NULL DEFAULT 0, `source` VARCHAR(10) NOT NULL COMMENT 'upload | manual', `file_name` VARCHAR(200) NULL, `file_sha256` CHAR(64) NULL, `checks_json` MEDIUMTEXT NULL, `status` VARCHAR(10) NOT NULL DEFAULT 'draft' COMMENT 'draft | accepted | void', `note` VARCHAR(300) NULL, `created_by` VARCHAR(100) NOT NULL, `created_at` DATETIME NOT NULL, `accepted_by` VARCHAR(100) NULL, `accepted_at` DATETIME NULL, `void_by` VARCHAR(100) NULL, `void_at` DATETIME NULL, `void_reason` VARCHAR(300) NULL, PRIMARY KEY (`id`), KEY `idx_brc_stmt_acct` (`bank_account_id`, `status`, `period_from`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `brc_line` ( `id` INT UNSIGNED NOT NULL AUTO_INCREMENT, `statement_id` INT UNSIGNED NOT NULL, `bank_account_id` INT UNSIGNED NOT NULL, `line_no` INT NOT NULL, `txn_date` DATE NOT NULL, `value_date` DATE NULL, `description` VARCHAR(400) NOT NULL DEFAULT '', `reference` VARCHAR(120) NULL, `money_in` DECIMAL(19,2) NOT NULL DEFAULT 0, `money_out` DECIMAL(19,2) NOT NULL DEFAULT 0, `balance` DECIMAL(19,2) NULL, `currency` VARCHAR(3) NOT NULL, `fx_rate` DECIMAL(18,6) NULL COMMENT 'LKR per unit on txn_date (1 for LKR)', `fx_source` VARCHAR(40) NULL, `lkr_amount` DECIMAL(19,2) NULL COMMENT '(money_in − money_out) × fx_rate', `category` VARCHAR(20) NOT NULL DEFAULT 'other' COMMENT 'receipt | payment | charge | transfer | interest | other', `charge_type` VARCHAR(40) NULL, `state` VARCHAR(12) NOT NULL DEFAULT 'open' COMMENT 'open | matched | timing | duplicate | excluded', `orig_json` TEXT NOT NULL, `edited` TINYINT(1) NOT NULL DEFAULT 0, `fingerprint` CHAR(40) NOT NULL, `created_at` DATETIME NOT NULL, PRIMARY KEY (`id`), KEY `idx_brc_line_acct` (`bank_account_id`, `txn_date`), KEY `idx_brc_line_stmt` (`statement_id`), KEY `idx_brc_line_fp` (`fingerprint`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `brc_fx_rate` ( `id` INT UNSIGNED NOT NULL AUTO_INCREMENT, `currency` VARCHAR(3) NOT NULL, `rate_date` DATE NOT NULL, `rate` DECIMAL(18,6) NOT NULL, `source` VARCHAR(40) NOT NULL, `note` VARCHAR(200) NULL, `created_by` VARCHAR(100) NOT NULL, `created_at` DATETIME NOT NULL, `updated_by` VARCHAR(100) NULL, `updated_at` DATETIME NULL, PRIMARY KEY (`id`), UNIQUE KEY `uq_brc_rate` (`currency`, `rate_date`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `brc_match` ( `id` INT UNSIGNED NOT NULL AUTO_INCREMENT, `bank_account_id` INT UNSIGNED NOT NULL, `method` VARCHAR(12) NOT NULL COMMENT 'suggested | manual', `bank_total` DECIMAL(19,2) NOT NULL COMMENT 'account currency', `bank_total_lkr` DECIMAL(19,2) NULL, `book_total` DECIMAL(19,2) NOT NULL COMMENT 'LKR (the ledger)', `difference_lkr` DECIMAL(19,2) NOT NULL DEFAULT 0, `diff_reason` VARCHAR(40) NULL COMMENT 'exchange rate | rounding | other', `status` VARCHAR(10) NOT NULL DEFAULT 'active' COMMENT 'active | undone', `note` VARCHAR(300) NULL, `created_by` VARCHAR(100) NOT NULL, `created_at` DATETIME NOT NULL, `undone_by` VARCHAR(100) NULL, `undone_at` DATETIME NULL, `undo_reason` VARCHAR(300) NULL, PRIMARY KEY (`id`), KEY `idx_brc_match_acct` (`bank_account_id`, `status`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `brc_match_item` ( `id` INT UNSIGNED NOT NULL AUTO_INCREMENT, `match_id` INT UNSIGNED NOT NULL, `side` VARCHAR(4) NOT NULL COMMENT 'bank | book', `line_id` INT UNSIGNED NULL, `book_key` VARCHAR(40) NULL COMMENT 'ledger row: ID.n', `amount` DECIMAL(19,2) NOT NULL COMMENT 'signed: + adds to funds', `item_date` DATE NOT NULL, `snapshot` TEXT NULL, PRIMARY KEY (`id`), KEY `idx_brc_mi_match` (`match_id`), KEY `idx_brc_mi_line` (`line_id`), KEY `idx_brc_mi_book` (`book_key`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `brc_mark` ( `id` INT UNSIGNED NOT NULL AUTO_INCREMENT, `bank_account_id` INT UNSIGNED NOT NULL, `side` VARCHAR(4) NOT NULL, `line_id` INT UNSIGNED NULL, `book_key` VARCHAR(40) NULL, `mark` VARCHAR(12) NOT NULL COMMENT 'timing | duplicate | excluded', `related` VARCHAR(60) NULL COMMENT 'duplicate-looking: the item it resembles', `expected_date` DATE NULL, `amount` DECIMAL(19,2) NOT NULL, `item_date` DATE NOT NULL, `note` VARCHAR(300) NULL, `status` VARCHAR(10) NOT NULL DEFAULT 'active' COMMENT 'active | cleared', `created_by` VARCHAR(100) NOT NULL, `created_at` DATETIME NOT NULL, `cleared_by` VARCHAR(100) NULL, `cleared_at` DATETIME NULL, `clear_reason` VARCHAR(300) NULL, PRIMARY KEY (`id`), KEY `idx_brc_mark_acct` (`bank_account_id`, `status`), KEY `idx_brc_mark_line` (`line_id`), KEY `idx_brc_mark_book` (`book_key`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `brc_transfer` ( `id` INT UNSIGNED NOT NULL AUTO_INCREMENT, `from_account_id` INT UNSIGNED NOT NULL, `to_account_id` INT UNSIGNED NOT NULL, `from_line_id` INT UNSIGNED NOT NULL, `to_line_id` INT UNSIGNED NOT NULL, `from_currency` VARCHAR(3) NOT NULL, `to_currency` VARCHAR(3) NOT NULL, `from_amount` DECIMAL(19,2) NOT NULL, `to_amount` DECIMAL(19,2) NOT NULL, `transfer_date` DATE NOT NULL, `implied_rate` DECIMAL(18,6) NULL, `daily_rate` DECIMAL(18,6) NULL, `daily_rate_source` VARCHAR(40) NULL, `rate_difference_lkr` DECIMAL(19,2) NULL COMMENT 'LKR received − amount × daily rate', `status` VARCHAR(10) NOT NULL DEFAULT 'active', `note` VARCHAR(300) NULL, `created_by` VARCHAR(100) NOT NULL, `created_at` DATETIME NOT NULL, `undone_by` VARCHAR(100) NULL, `undone_at` DATETIME NULL, `undo_reason` VARCHAR(300) NULL, PRIMARY KEY (`id`), KEY `idx_brc_tr_from` (`from_line_id`), KEY `idx_brc_tr_to` (`to_line_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `brc_opening` ( `id` INT UNSIGNED NOT NULL AUTO_INCREMENT, `bank_account_id` INT UNSIGNED NOT NULL, `description` VARCHAR(300) NOT NULL, `amount` DECIMAL(19,2) NOT NULL COMMENT 'part of (bank − book) at the start it explains, LKR', `evidence` VARCHAR(300) NULL, `status` VARCHAR(10) NOT NULL DEFAULT 'proposed' COMMENT 'proposed | accepted | rejected | withdrawn', `created_by` VARCHAR(100) NOT NULL, `created_at` DATETIME NOT NULL, `reviewed_by` VARCHAR(100) NULL, `reviewed_at` DATETIME NULL, `review_note` VARCHAR(300) NULL, PRIMARY KEY (`id`), KEY `idx_brc_open_acct` (`bank_account_id`, `status`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `brc_correction` ( `id` INT UNSIGNED NOT NULL AUTO_INCREMENT, `bank_account_id` INT UNSIGNED NOT NULL, `kind` VARCHAR(30) NOT NULL, `description` VARCHAR(400) NOT NULL, `entry_date` DATE NOT NULL, `entry_json` TEXT NOT NULL COMMENT 'proposed journal lines: ledger_code, dr, cr, narration', `amount` DECIMAL(19,2) NOT NULL, `currency` VARCHAR(3) NOT NULL DEFAULT 'LKR', `related_json` TEXT NULL, `status` VARCHAR(10) NOT NULL DEFAULT 'proposed' COMMENT 'proposed | approved | rejected | withdrawn', `created_by` VARCHAR(100) NOT NULL, `created_at` DATETIME NOT NULL, `reviewed_by` VARCHAR(100) NULL, `reviewed_at` DATETIME NULL, `review_note` VARCHAR(300) NULL, `posted_ref` VARCHAR(60) NULL COMMENT 'ledger entry posted by hand in the accounting module, recorded afterwards', `posted_noted_by` VARCHAR(100) NULL, `posted_noted_at` DATETIME NULL, PRIMARY KEY (`id`), KEY `idx_brc_corr_acct` (`bank_account_id`, `status`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `brc_day` ( `id` INT UNSIGNED NOT NULL AUTO_INCREMENT, `bank_account_id` INT UNSIGNED NOT NULL, `rec_date` DATE NOT NULL, `currency` VARCHAR(3) NOT NULL, `bank_closing` DECIMAL(19,2) NULL, `bank_closing_lkr` DECIMAL(19,2) NULL, `closing_rate` DECIMAL(18,6) NULL, `book_closing` DECIMAL(19,2) NULL, `difference_lkr` DECIMAL(19,2) NULL, `unexplained_lkr` DECIMAL(19,2) NULL, `status_code` VARCHAR(30) NOT NULL, `status_label` VARCHAR(120) NOT NULL, `snapshot` MEDIUMTEXT NOT NULL, `prepared_by` VARCHAR(100) NOT NULL, `prepared_at` DATETIME NOT NULL, `prepare_note` VARCHAR(300) NULL, `review_status` VARCHAR(10) NOT NULL DEFAULT 'prepared' COMMENT 'prepared | reviewed | returned', `reviewed_by` VARCHAR(100) NULL, `reviewed_at` DATETIME NULL, `review_note` VARCHAR(300) NULL, PRIMARY KEY (`id`), KEY `idx_brc_day_acct` (`bank_account_id`, `rec_date`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SET @cat = (SELECT id FROM menu_category WHERE category = 'Accounts' AND del = 0 ORDER BY id LIMIT 1);
INSERT INTO menu_list (cat_id, name, user, del, url, order_id, show_in_menu_bar) SELECT @cat, 'Daily Bank Reconciliation', 1, 0, 'accounts/daily_bank_rec', (SELECT COALESCE(MAX(m.order_id), 0) + 1 FROM menu_list m WHERE m.cat_id = @cat), 1 FROM DUAL WHERE @cat IS NOT NULL AND NOT EXISTS (SELECT 1 FROM menu_list x WHERE x.url = 'accounts/daily_bank_rec' AND x.del = 0);
INSERT INTO menu_list (cat_id, name, user, del, url, order_id, show_in_menu_bar) SELECT @cat, 'Daily Bank Reconciliation — prepare (import, match, propose)', 1, 0, 'accounts/daily_bank_rec/prepare', (SELECT COALESCE(MAX(m.order_id), 0) + 1 FROM menu_list m WHERE m.cat_id = @cat), 0 FROM DUAL WHERE @cat IS NOT NULL AND NOT EXISTS (SELECT 1 FROM menu_list x WHERE x.url = 'accounts/daily_bank_rec/prepare' AND x.del = 0);
INSERT INTO menu_list (cat_id, name, user, del, url, order_id, show_in_menu_bar) SELECT @cat, 'Daily Bank Reconciliation — review (confirm mappings, approve, sign off)', 1, 0, 'accounts/daily_bank_rec/review', (SELECT COALESCE(MAX(m.order_id), 0) + 1 FROM menu_list m WHERE m.cat_id = @cat), 0 FROM DUAL WHERE @cat IS NOT NULL AND NOT EXISTS (SELECT 1 FROM menu_list x WHERE x.url = 'accounts/daily_bank_rec/review' AND x.del = 0);
-- grants: System Administrator (1) all; Accounts (30) view + prepare; Management Approver (29) view + review; Bank Authoriser (35) and Auditor (34) view
INSERT INTO user_privileges (group_id, user_id, menu_id) SELECT 1, COALESCE((SELECT MIN(p.user_id) FROM user_privileges p WHERE p.group_id = 1), 1), m.id FROM menu_list m WHERE m.url = 'accounts/daily_bank_rec' AND m.del = 0 AND NOT EXISTS (SELECT 1 FROM user_privileges q WHERE q.group_id = 1 AND q.menu_id = m.id);
INSERT INTO user_privileges (group_id, user_id, menu_id) SELECT 1, COALESCE((SELECT MIN(p.user_id) FROM user_privileges p WHERE p.group_id = 1), 1), m.id FROM menu_list m WHERE m.url = 'accounts/daily_bank_rec/prepare' AND m.del = 0 AND NOT EXISTS (SELECT 1 FROM user_privileges q WHERE q.group_id = 1 AND q.menu_id = m.id);
INSERT INTO user_privileges (group_id, user_id, menu_id) SELECT 1, COALESCE((SELECT MIN(p.user_id) FROM user_privileges p WHERE p.group_id = 1), 1), m.id FROM menu_list m WHERE m.url = 'accounts/daily_bank_rec/review' AND m.del = 0 AND NOT EXISTS (SELECT 1 FROM user_privileges q WHERE q.group_id = 1 AND q.menu_id = m.id);
INSERT INTO user_privileges (group_id, user_id, menu_id) SELECT 30, COALESCE((SELECT MIN(p.user_id) FROM user_privileges p WHERE p.group_id = 30), 1), m.id FROM menu_list m WHERE m.url = 'accounts/daily_bank_rec' AND m.del = 0 AND NOT EXISTS (SELECT 1 FROM user_privileges q WHERE q.group_id = 30 AND q.menu_id = m.id);
INSERT INTO user_privileges (group_id, user_id, menu_id) SELECT 30, COALESCE((SELECT MIN(p.user_id) FROM user_privileges p WHERE p.group_id = 30), 1), m.id FROM menu_list m WHERE m.url = 'accounts/daily_bank_rec/prepare' AND m.del = 0 AND NOT EXISTS (SELECT 1 FROM user_privileges q WHERE q.group_id = 30 AND q.menu_id = m.id);
INSERT INTO user_privileges (group_id, user_id, menu_id) SELECT 29, COALESCE((SELECT MIN(p.user_id) FROM user_privileges p WHERE p.group_id = 29), 1), m.id FROM menu_list m WHERE m.url = 'accounts/daily_bank_rec' AND m.del = 0 AND NOT EXISTS (SELECT 1 FROM user_privileges q WHERE q.group_id = 29 AND q.menu_id = m.id);
